#include <vector>
#include <algorithm>
#include <string>
#include <cmath>

class Solution {
private:
    bool isPal(long long x) {
        std::string s = std::to_string(x);
        int l = 0, r = s.size() - 1;
        while (l < r) {
            if (s[l++] != s[r--]) return false;
        }
        return true;
    }
    long long getCost(const std::vector<int>& nums, long long y) {
        long long res = 0;
        for (int x : nums) res += std::abs(x - y);
        return res;
    }
public:
    long long minimumCost(std::vector<int>& nums) {
        std::sort(nums.begin(), nums.end());
        int n = nums.size();
        long long med = nums[n / 2];
        long long p1 = med;
        while (!isPal(p1)) --p1;
        long long p2 = med;
        while (!isPal(p2)) ++p2;
        return std::min(getCost(nums, p1), getCost(nums, p2));
    }
};

import java.util.Arrays;

class Solution {
    private boolean isPal(long x) {
        String s = Long.toString(x);
        int l = 0, r = s.length() - 1;
        while (l < r) {
            if (s.charAt(l++) != s.charAt(r--)) return false;
        }
        return true;
    }

    private long getCost(int[] nums, long y) {
        long res = 0;
        for (int x : nums) res += Math.abs(x - y);
        return res;
    }

    public long minimumCost(int[] nums) {
        Arrays.sort(nums);
        int n = nums.length;
        long med = nums[n / 2];
        long p1 = med;
        while (!isPal(p1)) p1--;
        long p2 = med;
        while (!isPal(p2)) p2++;
        return Math.min(getCost(nums, p1), getCost(nums, p2));
    }
}

